tests:
from solution import business_day_count


def test_same_day_weekday():
    assert business_day_count('2024-01-02', '2024-01-02') == 1


def test_same_day_weekend():
    assert business_day_count('2024-01-06', '2024-01-06') == 0


def test_single_weekday_span():
    assert business_day_count('2024-01-01', '2024-01-01') == 1


def test_single_weekend_span():
    assert business_day_count('2024-01-07', '2024-01-07') == 0


def test_week_span():
    assert business_day_count('2024-01-01', '2024-01-07') == 5


def test_two_week_span():
    assert business_day_count('2024-01-01', '2024-01-14') == 10


def test_start_after_end():
    assert business_day_count('2024-01-10', '2024-01-01') == 0


def test_span_with_holidays_not_considered():
    assert business_day_count('2024-12-23', '2024-12-27') == 5


def test_leap_year_february():
    assert business_day_count('2024-02-26', '2024-03-01') == 5


def test_non_leap_year_february():
    assert business_day_count('2023-02-27', '2023-03-01') == 3


def test_year_boundary():
    assert business_day_count('2023-12-29', '2024-01-02') == 3


def test_long_span():
    assert business_day_count('2024-01-01', '2024-12-31') == 262


def test_weekend_to_weekend():
    assert business_day_count('2024-01-06', '2024-01-07') == 0


def test_weekend_to_weekday():
    assert business_day_count('2024-01-06', '2024-01-08') == 1


def test_weekday_to_weekend():
    assert business_day_count('2024-01-05', '2024-01-06') == 1


def test_mixed_types_not_required():
    # Inputs are strings; no type checking required
    assert business_day_count('2024-01-01', '2024-01-02') == 2
